/// <reference types="@vitest/browser-playwright" />
import { createModal, createTooltip, createDropdown, createCollapse, Lock } from '@src/browser'
import { requireValue, waitForCondition, waitForDelay } from '@orkestrel/test'
import { cdp, userEvent, commands, page } from 'vitest/browser'
import { expect, it } from 'vitest'
import { createOracle } from '../../setupBrowser.js'

it('reads native replay, capture installation, and the queued close interval', async () => {
	const oracle = await createOracle({ plugin: 'Modal', markup: '<dialog id="target"><button>Inside</button></dialog><button id="invoker" commandfor="target" command="show-modal">Open</button>' })
	const dialog = requireValue(oracle.root.querySelector('dialog'))
	const controller = new AbortController()
	const readings: unknown[] = []
	let opening = false
	let capture = 0
	let target = 0
	try {
		oracle.document.addEventListener('beforetoggle', (event) => {
			if (event.target !== dialog || capture) return
			capture++
			dialog.addEventListener('beforetoggle', (toggle) => {
				target++
				if (toggle.newState !== 'open' || opening) return
				toggle.preventDefault()
				opening = true
				dialog.showModal()
				opening = false
			}, { signal: controller.signal })
		}, { capture: true, signal: controller.signal })
		dialog.show()
		readings.push({ capture, target, open: dialog.open, modal: dialog.matches(':modal') })
		expect(dialog.matches(':modal')).toBe(true)
		expect(target).toBe(2)
		controller.abort()
		dialog.close()
		await waitForDelay(25)
		const received: string[] = []
		oracle.document.addEventListener('command', () => {
			dialog.addEventListener('command', (event) => { received.push(event.type); event.preventDefault() }, { once: true })
		}, { capture: true, once: true })
		requireValue(oracle.root.querySelector<HTMLButtonElement>('#invoker')).click()
		readings.push({ commands: received, open: dialog.open })
		expect(received).toEqual(['command'])
		expect(dialog.open).toBe(false)
		requireValue(oracle.root.querySelector<HTMLButtonElement>('#invoker')).click()
		expect(dialog.open).toBe(true)
		let closing = true
		const sequence: unknown[] = []
		dialog.addEventListener('close', () => { sequence.push({ event: 'close', open: dialog.open }); closing = false }, { once: true })
		dialog.addEventListener('beforetoggle', (event) => { sequence.push({ event: event.newState, closing }) })
		dialog.close()
		dialog.showModal()
		await waitForCondition('queued close delivered', () => !closing)
		readings.push(sequence)
		await commands.writeFile('tmp/codex/check-native.json', JSON.stringify(readings, null, 2))
	} finally { controller.abort(); oracle.destroy() }
})

it('reads refused promotion with the proposed reset and attribute restoration', async () => {
	const oracle = await createOracle({ plugin: 'Tooltip', markup: '<style>@layer reset { .dropdown-menu[popover], .tooltip[popover], .popover[popover] { inset:auto; margin:0; border:0; padding:0; overflow:visible; color:inherit; background:transparent } }</style>' })
	try {
		const readings: unknown[] = []
		for (const family of ['dropdown-menu', 'tooltip', 'popover']) {
			const panel = oracle.document.createElement('div')
			panel.className = `${family} show`
			panel.textContent = 'Panel content'
			oracle.root.append(panel)
			const ordinary = oracle.window.getComputedStyle(panel).display
			panel.setAttribute('popover', 'manual')
			panel.addEventListener('beforetoggle', (event) => { if (event.newState === 'open') event.preventDefault() }, { once: true })
			panel.showPopover()
			const refused = oracle.window.getComputedStyle(panel).display
			const refusedBox = panel.getBoundingClientRect().height
			panel.removeAttribute('popover')
			const restored = oracle.window.getComputedStyle(panel).display
			readings.push({ family, ordinary, refused, refusedBox, restored })
			expect(ordinary).not.toBe('none')
			expect(restored).toBe(ordinary)
			panel.remove()
		}
		await commands.writeFile('tmp/codex/check-fallback.json', JSON.stringify(readings, null, 2))
	} finally { oracle.destroy() }
})

it('reads the live Trap with native modality and ordinary control', async () => {
	const readings: unknown[] = []
	for (const native of [false, true]) {
		const oracle = await createOracle({ plugin: 'Modal', markup: '<button id="outside">Outside</button><dialog class="modal" tabindex="-1"><div class="modal-dialog"><button id="first">First</button><button id="last">Last</button></div></dialog><button id="after">After</button><style>@layer reset { dialog.modal { margin:0; border:0; padding:0; max-width:none; max-height:none; color:inherit; background:transparent } dialog.modal::backdrop { background:transparent } }</style>' })
		const dialog = requireValue(oracle.root.querySelector('dialog'))
		const modal = createModal(dialog)
		try {
			modal.show()
			if (native) { dialog.setAttribute('closedby', 'none'); dialog.showModal() }
			requireValue(oracle.root.querySelector<HTMLButtonElement>('#last')).focus()
			await userEvent.keyboard('{Tab}')
			readings.push({ native, focus: oracle.document.activeElement?.id || oracle.document.activeElement?.tagName, frameFocused: document.activeElement === oracle.frame })
		} finally { modal.destroy(); oracle.destroy() }
	}
	await commands.writeFile('tmp/codex/check-tab.json', JSON.stringify(readings, null, 2))
})

it('reads the classic scrollbar CDP gate and stable lock footprint', async () => {
	const session = cdp()
	const readings: unknown[] = []
	try {
		for (const hidden of [true, false]) {
			await session.send('Emulation.setScrollbarsHidden', { hidden })
			const oracle = await createOracle({ plugin: 'Modal', frame: { width: 800, height: 600 }, markup: '<div style="height:2400px">Overflow</div>' })
			const lock = new Lock(oracle.document)
			try {
				readings.push({ hidden, width: lock.width })
				oracle.document.documentElement.style.scrollbarGutter = 'stable'
				oracle.root.style.paddingRight = '7px'
				lock.acquire()
				readings.push({ hidden, stable: true, width: lock.width, padding: oracle.root.style.paddingRight, saved: oracle.root.getAttribute('data-bs-padding-right') })
			} finally { lock.destroy(); oracle.destroy() }
		}
		await commands.writeFile('tmp/codex/check-scrollbar.json', JSON.stringify(readings, null, 2))
	} finally { await session.send('Emulation.setScrollbarsHidden', { hidden: true }) }
})

it('reads authored popover restoration and nested dialog command targets', async () => {
	const oracle = await createOracle({ plugin: 'Modal', markup: '<dialog id="outer"><dialog id="inner"></dialog><button commandfor="inner" command="show-modal">Open inner</button></dialog><div id="panel" popover="manual">Panel</div>' })
	try {
		const outer = requireValue(oracle.root.querySelector<HTMLDialogElement>('#outer'))
		const inner = requireValue(oracle.root.querySelector<HTMLDialogElement>('#inner'))
		const panel = requireValue(oracle.root.querySelector<HTMLElement>('#panel'))
		const events: unknown[] = []
		outer.addEventListener('command', (event) => { events.push({ target: event.target === inner ? 'inner' : 'outer', bubbles: event.bubbles }) })
		outer.showModal()
		requireValue(oracle.root.querySelector<HTMLButtonElement>('button')).click()
		panel.showPopover()
		panel.hidePopover()
		panel.showPopover()
		await commands.writeFile('tmp/codex/check-author.json', JSON.stringify({ events, inner: inner.open, restoredPopoverReopens: panel.matches(':popover-open') }, null, 2))
		expect(inner.open).toBe(true)
		expect(panel.matches(':popover-open')).toBe(true)
		const written = oracle.document.createElement('dialog')
		oracle.root.append(written)
		const changes: string[] = []
		for (const name of ['beforetoggle', 'toggle', 'close']) written.addEventListener(name, () => changes.push(name))
		written.open = true
		await waitForDelay(25)
		await commands.writeFile('tmp/codex/check-open-attribute.json', JSON.stringify({ open: written.open, events: changes }, null, 2))
	} finally { oracle.destroy() }
})

it('reads intrinsic growth against the real measured pixel path', async () => {
	const readings: unknown[] = []
	for (const intrinsic of [false, true]) {
		const oracle = await createOracle({ plugin: 'Collapse', markup: '<div class="collapse" style="width:200px"><div style="height:120px"></div></div>' })
		const panel = requireValue(oracle.root.querySelector<HTMLElement>('.collapse'))
		const child = requireValue(panel.firstElementChild)
		const collapse = createCollapse(panel, { toggle: false })
		try {
			if (intrinsic) {
				panel.style.setProperty('interpolate-size', 'allow-keywords')
				panel.classList.remove('collapse')
				panel.classList.add('collapsing')
				panel.style.height = '0px'
				void panel.offsetHeight
				panel.style.height = 'auto'
			} else collapse.show()
			await waitForCondition('opening has advanced', () => panel.getBoundingClientRect().height > 20)
			child.setAttribute('style', 'height:240px')
			await waitForCondition('opening near completion', () => panel.getAnimations().some((animation) => typeof animation.currentTime === 'number' && animation.currentTime > 270))
			readings.push({ intrinsic, height: panel.getBoundingClientRect().height, endpoint: panel.style.height, phase: collapse.phase })
			if (!intrinsic) await waitForCondition('collapse shown', () => collapse.phase === 'shown')
		} finally { collapse.destroy(); oracle.destroy() }
	}
	await commands.writeFile('tmp/codex/check-intrinsic.json', JSON.stringify(readings, null, 2))
})

it('reads transformed clipping and manual promotion with a visible-anchor control', async () => {
	const readings: unknown[] = []
	for (const transform of [false, true]) {
		for (const promoted of [false, true]) {
			const oracle = await createOracle({ plugin: 'Dropdown', markup: `<style>@layer reset { [popover] { inset:auto; margin:0; border:0; padding:0; overflow:visible; background:transparent } }</style><div style="position:absolute;left:50px;top:50px;width:240px;height:50px;overflow:hidden;${transform ? 'transform:translateZ(0)' : ''}"><button data-bs-toggle="dropdown" style="margin:10px">Toggle</button><div class="dropdown-menu"><button class="dropdown-item">Entry</button><button class="dropdown-item">Next</button></div></div>` })
			const toggle = requireValue(oracle.root.querySelector<HTMLButtonElement>('button'))
			const dropdown = createDropdown(toggle)
			try {
				dropdown.show()
				const panel = requireValue(dropdown.menu)
				if (promoted) { panel.setAttribute('popover', 'manual'); panel.showPopover({ source: toggle }); dropdown.update() }
				await waitForDelay(40)
				const box = panel.getBoundingClientRect()
				const x = box.x + box.width / 2
				const y = box.bottom - 10
				readings.push({ transform, promoted, box: { x: box.x, y: box.y, width: box.width, height: box.height }, hit: oracle.document.elementsFromPoint(x, y).some((element) => element === panel || panel.contains(element)), visibility: oracle.window.getComputedStyle(panel).getPropertyValue('position-visibility') })
			} finally { dropdown.destroy(); oracle.destroy() }
		}
	}
	await commands.writeFile('tmp/codex/check-clip.json', JSON.stringify(readings, null, 2))
})

it('reads tip pixels over modal content and a known paint-order control', async () => {
	const readings: unknown[] = []
	for (const native of [false, true]) {
		for (const promoted of [false, true]) {
			const oracle = await createOracle({ plugin: 'Modal', markup: '<style>@layer reset { dialog.modal {margin:0;border:0;padding:0;max-width:none;max-height:none;color:inherit;background:transparent} dialog.modal::backdrop{background:transparent} .tooltip[popover]{inset:auto;margin:0;border:0;padding:0;overflow:visible;background:transparent} } .modal-content { height:300px; background:rgb(255,0,0) } .tooltip-inner { background:rgb(0,255,0);color:rgb(0,255,0);border-radius:0 } </style><dialog class="modal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><button style="margin:100px 100px 0" title="Measured tooltip">Trigger</button></div></div></dialog>' })
			const dialog = requireValue(oracle.root.querySelector('dialog'))
			const modal = createModal(dialog)
			const tip = createTooltip(requireValue(dialog.querySelector('button')), { animation: false })
			try {
				modal.show()
				if (native) { dialog.setAttribute('closedby', 'none'); dialog.showModal() }
				tip.show()
				const panel = requireValue(tip.panel)
				panel.style.opacity = '1'
				if (promoted) { panel.setAttribute('popover', 'manual'); panel.showPopover(); tip.update() }
				await waitForDelay(40)
				const box = requireValue(panel.querySelector('.tooltip-inner')).getBoundingClientRect()
				const screenshot = await page.screenshot({ element: oracle.frame, save: false })
				await commands.writeFile(`tmp/codex/check-paint-${native}-${promoted}.png`, screenshot, 'base64')
				const bitmap = await createImageBitmap(await (await fetch(`data:image/png;base64,${screenshot}`)).blob())
				const canvas = document.createElement('canvas')
				canvas.width = bitmap.width
				canvas.height = bitmap.height
				const context = requireValue(canvas.getContext('2d'))
				context.drawImage(bitmap, 0, 0)
				const left = oracle.frame.clientLeft + box.x + box.width / 2
				const top = oracle.frame.clientTop + box.y + box.height / 2
				const x = Math.floor(left * bitmap.width / oracle.frame.offsetWidth)
				const y = Math.floor(top * bitmap.height / oracle.frame.offsetHeight)
				const pixel = [...context.getImageData(x, y, 1, 1).data]
				readings.push({ native, promoted, pixel, point: { x, y }, hit: oracle.document.elementsFromPoint(box.x + box.width / 2, box.y + box.height / 2).some((element) => panel.contains(element)) })
				await commands.writeFile('tmp/codex/check-paint.json', JSON.stringify(readings, null, 2))
				if (!native) expect(pixel).toEqual([0, 255, 0, 255])
				bitmap.close()
			} finally { tip.destroy(); modal.destroy(); oracle.destroy() }
		}
	}
	await commands.writeFile('tmp/codex/check-paint.json', JSON.stringify(readings, null, 2))
})

it('reads clipped-anchor visibility against visible and always controls', async () => {
	const readings: unknown[] = []
	for (const family of ['dropdown', 'tooltip']) {
		for (const engine of [true, false]) {
		const oracle = await createOracle({ plugin: 'Dropdown', markup: '<div id="scroller" style="position:absolute;left:80px;top:180px;width:240px;height:70px;overflow:auto"><button data-bs-toggle="dropdown" title="Clipped anchor">Toggle</button><div class="dropdown-menu"><button class="dropdown-item">Entry</button></div><div style="height:400px"></div></div>' })
		const scroller = requireValue(oracle.root.querySelector<HTMLElement>('#scroller'))
		const toggle = requireValue(scroller.querySelector('button'))
		const dropdown = engine && family === 'dropdown' ? createDropdown(toggle) : undefined
		const tip = engine && family === 'tooltip' ? createTooltip(toggle, { animation: false, trigger: { hover: false, focus: false, click: false } }) : undefined
		const bootstrap = engine ? undefined : oracle.construct(toggle, family === 'dropdown' ? 'Dropdown' : 'Tooltip', { animation: false, trigger: 'manual' })
		try {
			dropdown?.show()
			tip?.show()
			bootstrap?.call('show')
			const panel = requireValue(dropdown?.menu ?? tip?.panel ?? oracle.root.querySelector<HTMLElement>(family === 'dropdown' ? '.dropdown-menu' : '.tooltip'))
			for (const scroll of [0, 80]) {
				scroller.scrollTop = scroll
				dropdown?.update()
				tip?.update()
				bootstrap?.call('update')
				await waitForDelay(40)
				for (const always of [false, true]) {
					panel.style.setProperty('position-visibility', always ? 'always' : 'anchors-visible')
					await waitForDelay(25)
					const box = panel.getBoundingClientRect()
					readings.push({ family, engine, scroll, always, x: box.x, y: box.y, shown: panel.classList.contains('show'), visibility: oracle.window.getComputedStyle(panel).getPropertyValue('position-visibility'), hit: oracle.document.elementsFromPoint(box.x + box.width / 2, box.y + box.height / 2).some((element) => panel.contains(element)) })
				}
			}
		} finally { dropdown?.destroy(); tip?.destroy(); bootstrap?.call('dispose'); oracle.destroy() }
		}
	}
	await commands.writeFile('tmp/codex/check-visibility.json', JSON.stringify(readings, null, 2))
})
